use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

use crate::plan_slots::{PlanSlotFacts, PlanSlotState};

/// The display summaries of the occupied plan slots, regenerated by the host after each send.
pub const SLOT_OVERVIEW_FILE: &str = "slots.runplanner.json";
pub const SLOT_OVERVIEW_FORMAT: &str = "run-planner-slot-overview";
pub const SLOT_OVERVIEW_FORMAT_VERSION: u8 = 1;
pub const MAX_SLOT_SUMMARY_BYTES: usize = 4096;
const MAX_SUMMARY_TEXT_CHARS: usize = 200;
// Twelve entries of at most one summary each, with their identities.
pub const MAX_SLOT_OVERVIEW_BYTES: usize = 65_536;

/// The planner's display summary of one plan, computed when it is sent.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SlotSummary {
    /// Picker text, such as "Circe - Surface".
    pub label: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub plan_name: Option<String>,
    /// ISO 8601 send time.
    pub sent_at: String,
    /// Such as "Circe (Staff)".
    pub aspect: String,
    pub route: String,
    pub end_biome: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub starting_keepsake: Option<String>,
    /// The configured Fear total the Oath shows.
    pub starting_fear: u32,
    /// Such as "Thessaly · Boss"; absent for a run from the start.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub practice_start: Option<String>,
}

/// One occupied slot's summary with the identity of the slot file it describes. Under
/// `flatten` the summary's `deny_unknown_fields` does not apply, so reading back is tolerant.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SlotOverviewEntry {
    #[serde(flatten)]
    pub summary: SlotSummary,
    pub build_id: String,
    pub fingerprint: String,
}

#[derive(Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SlotOverview {
    pub format: String,
    pub format_version: u8,
    pub slots: BTreeMap<u8, SlotOverviewEntry>,
}

impl SlotSummary {
    /// Refuses a summary too large or with blank or overlong text before anything is written.
    pub fn validate(&self) -> Result<(), String> {
        let texts = [
            Some(&self.label),
            self.plan_name.as_ref(),
            Some(&self.sent_at),
            Some(&self.aspect),
            Some(&self.route),
            Some(&self.end_biome),
            self.starting_keepsake.as_ref(),
            self.practice_start.as_ref(),
        ];
        let valid = texts
            .into_iter()
            .flatten()
            .all(|text| !text.trim().is_empty() && text.chars().count() <= MAX_SUMMARY_TEXT_CHARS);
        let size = serde_json::to_vec(self).map_or(usize::MAX, |bytes| bytes.len());
        (valid && size <= MAX_SLOT_SUMMARY_BYTES)
            .then_some(())
            .ok_or_else(|| "Invalid plan slot summary.".to_owned())
    }
}

/// Reads the previous overview; a missing, linked, oversized or invalid file holds no entries.
pub fn read_overview(path: &Path) -> BTreeMap<u8, SlotOverviewEntry> {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return BTreeMap::new();
    };
    if metadata.file_type().is_symlink()
        || !metadata.is_file()
        || metadata.len() > MAX_SLOT_OVERVIEW_BYTES as u64
    {
        return BTreeMap::new();
    }
    let mut bytes = Vec::new();
    let read = fs::File::open(path).and_then(|file| {
        file.take(MAX_SLOT_OVERVIEW_BYTES as u64 + 1)
            .read_to_end(&mut bytes)
    });
    read.ok()
        .and_then(|_| serde_json::from_slice::<SlotOverview>(&bytes).ok())
        .filter(|overview| {
            overview.format == SLOT_OVERVIEW_FORMAT
                && overview.format_version == SLOT_OVERVIEW_FORMAT_VERSION
        })
        .map(|overview| overview.slots)
        .unwrap_or_default()
}

/// The overview for the slots as they are now: a slot keeps an entry only while its file
/// still holds the plan the entry describes; `sent` replaces the entry of the slot just written.
/// A readable slot without a known summary has no entry.
pub fn regenerate(
    previous: BTreeMap<u8, SlotOverviewEntry>,
    slots: &[PlanSlotFacts],
    sent: Option<(u8, SlotSummary)>,
) -> SlotOverview {
    let mut previous = previous;
    let mut sent = sent;
    let entries = slots
        .iter()
        .filter_map(|facts| {
            if !matches!(facts.state, PlanSlotState::Present | PlanSlotState::Stale) {
                return None;
            }
            let build_id = facts.build_id.clone()?;
            let fingerprint = facts.plan_fingerprint.clone()?;
            let summary = match sent.take() {
                Some((slot, summary)) if slot == facts.slot => summary,
                other => {
                    sent = other;
                    previous
                        .remove(&facts.slot)
                        .filter(|entry| {
                            entry.build_id == build_id && entry.fingerprint == fingerprint
                        })?
                        .summary
                }
            };
            Some((
                facts.slot,
                SlotOverviewEntry {
                    summary,
                    build_id,
                    fingerprint,
                },
            ))
        })
        .collect();
    SlotOverview {
        format: SLOT_OVERVIEW_FORMAT.to_owned(),
        format_version: SLOT_OVERVIEW_FORMAT_VERSION,
        slots: entries,
    }
}

/// Refuses an overview larger than a reader accepts, rather than writing one it would drop.
pub fn encode_overview(overview: &SlotOverview) -> Result<String, String> {
    let encoded = serde_json::to_string(overview).expect("the slot overview always encodes");
    (encoded.len() <= MAX_SLOT_OVERVIEW_BYTES)
        .then_some(encoded)
        .ok_or_else(|| format!("slot overview exceeds the {MAX_SLOT_OVERVIEW_BYTES}-byte limit"))
}

#[cfg(test)]
pub mod test_support {
    use super::SlotSummary;

    pub fn summary(label: &str) -> SlotSummary {
        SlotSummary {
            label: label.to_owned(),
            plan_name: Some("Surface Phial run".to_owned()),
            sent_at: "2026-10-12T10:00:00.000Z".to_owned(),
            aspect: "Circe (Staff)".to_owned(),
            route: "Surface".to_owned(),
            end_biome: "Olympus".to_owned(),
            starting_keepsake: Some("Silver Wheel".to_owned()),
            starting_fear: 12,
            practice_start: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::test_support::summary;
    use super::*;
    use crate::game_target::test_support::TemporaryDirectory;

    fn facts(slot: u8, state: PlanSlotState, build: Option<&str>, print: &str) -> PlanSlotFacts {
        PlanSlotFacts {
            slot,
            state,
            modified_at_ms: None,
            build_id: build.map(str::to_owned),
            route_key: None,
            biome_keys: Vec::new(),
            plan_fingerprint: (state != PlanSlotState::Empty).then(|| print.to_owned()),
            project_id: None,
            display_name: None,
            weapon_key: None,
            aspect_key: None,
        }
    }

    fn entry(label: &str, build: &str, print: &str) -> SlotOverviewEntry {
        SlotOverviewEntry {
            summary: summary(label),
            build_id: build.to_owned(),
            fingerprint: print.to_owned(),
        }
    }

    #[test]
    fn regeneration_keeps_only_entries_that_still_describe_their_slot() {
        let previous = BTreeMap::from([
            (1, entry("kept", "b", "f1")),
            (2, entry("replaced elsewhere", "b", "old")),
            (3, entry("cleared", "b", "f3")),
            (4, entry("rebuilt", "a", "f4")),
            (5, entry("overwritten", "b", "f5")),
        ]);
        let slots = [
            facts(1, PlanSlotState::Present, Some("b"), "f1"),
            facts(2, PlanSlotState::Present, Some("b"), "f2"),
            facts(3, PlanSlotState::Empty, None, ""),
            facts(4, PlanSlotState::Stale, Some("b"), "f4"),
            facts(5, PlanSlotState::Present, Some("b"), "f5b"),
            facts(6, PlanSlotState::Stale, None, "bare"),
            facts(7, PlanSlotState::Unreadable, None, ""),
            facts(12, PlanSlotState::Present, Some("b"), "f12"),
        ];
        let overview = regenerate(previous, &slots, Some((5, summary("sent"))));
        assert_eq!(
            overview.slots,
            BTreeMap::from([
                (1, entry("kept", "b", "f1")),
                (5, entry("sent", "b", "f5b"))
            ])
        );
        let stale = regenerate(
            BTreeMap::from([(4, entry("stale", "a", "f4"))]),
            &[facts(4, PlanSlotState::Stale, Some("a"), "f4")],
            None,
        );
        assert_eq!(stale.slots.len(), 1);
    }

    #[test]
    fn the_overview_encodes_numbered_slots_and_omits_absent_fields() {
        let mut practice = summary("Circe - Surface");
        practice.plan_name = None;
        practice.starting_keepsake = None;
        practice.practice_start = Some("Thessaly · Boss".to_owned());
        let overview = regenerate(
            BTreeMap::new(),
            &[
                facts(2, PlanSlotState::Present, Some("b"), "f2"),
                facts(10, PlanSlotState::Present, Some("b"), "f10"),
            ],
            Some((10, practice)),
        );
        let encoded = encode_overview(&overview).unwrap();
        assert_eq!(
            encoded,
            r#"{"format":"run-planner-slot-overview","formatVersion":1,"slots":{"10":{"label":"Circe - Surface","sentAt":"2026-10-12T10:00:00.000Z","aspect":"Circe (Staff)","route":"Surface","endBiome":"Olympus","startingFear":12,"practiceStart":"Thessaly · Boss","buildId":"b","fingerprint":"f10"}}}"#
        );
        let empty = regenerate(BTreeMap::new(), &[], None);
        assert_eq!(
            encode_overview(&empty).unwrap(),
            r#"{"format":"run-planner-slot-overview","formatVersion":1,"slots":{}}"#
        );
    }

    #[test]
    fn reading_the_previous_overview_tolerates_missing_and_invalid_files() {
        let temporary = TemporaryDirectory::new("overview-read");
        let path = temporary.0.join(SLOT_OVERVIEW_FILE);
        assert!(read_overview(&path).is_empty());
        let overview = SlotOverview {
            format: SLOT_OVERVIEW_FORMAT.to_owned(),
            format_version: SLOT_OVERVIEW_FORMAT_VERSION,
            slots: (1..=12)
                .map(|slot| (slot, entry(&"x".repeat(200), "b", &format!("f{slot}"))))
                .collect(),
        };
        let encoded = encode_overview(&overview).unwrap();
        fs::write(&path, &encoded).unwrap();
        assert_eq!(read_overview(&path).len(), 12);
        for invalid in [
            encoded.replace("formatVersion\":1", "formatVersion\":2"),
            encoded.replace("run-planner-slot-overview", "run-planner-slot"),
            encoded.replace("\"fingerprint\"", "\"print\""),
            "not json".to_owned(),
        ] {
            fs::write(&path, invalid).unwrap();
            assert!(read_overview(&path).is_empty());
        }
    }

    #[test]
    fn an_overview_larger_than_a_reader_accepts_is_refused() {
        let oversized = SlotOverview {
            format: SLOT_OVERVIEW_FORMAT.to_owned(),
            format_version: SLOT_OVERVIEW_FORMAT_VERSION,
            slots: (1..=12)
                .map(|slot| (slot, entry("label", "b", &"f".repeat(6000))))
                .collect(),
        };
        assert_eq!(
            encode_overview(&oversized),
            Err("slot overview exceeds the 65536-byte limit".to_owned())
        );
    }

    #[test]
    fn summaries_with_blank_or_overlong_text_are_refused() {
        assert_eq!(summary("Circe - Surface").validate(), Ok(()));
        let mut blank = summary(" ");
        assert!(blank.validate().is_err());
        blank.label = "x".repeat(201);
        assert!(blank.validate().is_err());
        let mut keepsake = summary("ok");
        keepsake.starting_keepsake = Some(String::new());
        assert!(keepsake.validate().is_err());
        let decoded: Result<SlotSummary, _> = serde_json::from_str(
            r#"{"label":"a","sentAt":"t","aspect":"a","route":"r","endBiome":"e","startingFear":0,"arcana":[]}"#,
        );
        assert!(decoded.is_err());
    }
}
